def transform(grid):
 a=[r[:] for r in grid]; H=len(a); W=len(a[0]); centers=[]
 for r in range(2,H,7):
  for c in range(2,W,7):
   if a[r][c] not in (0,4): centers.append((r,c,a[r][c]))
 # link same-colored centers sharing row/column, paint non-interior cells along direct segment
 for i,(r,c,v) in enumerate(centers):
  for rr,cc,w in centers[i+1:]:
   if v!=w: continue
   if r==rr:
    for x in range(min(c,cc)+1,max(c,cc)):
     if a[r][x] in (0,4): a[r][x]=v
   if c==cc:
    for y in range(min(r,rr)+1,max(r,rr)):
     if a[y][c] in (0,4): a[y][c]=v
 return a
