 # find uniform 3x3 interiors
 for r in range(1,H-1):
  for c in range(1,W-1):
   v=a[r][c]
   if v not in (0,4) and all(a[y][x]==v for y in range(r-1,r+2) for x in range(c-1,c+2)):
    centers.append((r,c,v))
 for i,(r,c,v) in enumerate(centers):
  for rr,cc,w in centers[i+1:]:
   if w!=v: continue
   if r==rr:
    for x in range(c+1,cc):
     if a[r][x] in (0,4): a[r][x]=v
   elif c==cc:
    for y in range(r+1,rr):
     if a[y][c] in (0,4): a[y][c]=v
 return a
